select case when duration_sec >= 406 then 'high' when duration_sec >= 109 then 'mid' else 'low' end as duration_sec_bucket, session_id, event_type, sum(duration_sec) as total_duration_sec, max(event_time) as last_event_time from web_events where to_date(event_time) < '2023-08-01' or duration_sec between 291 and 344 group by 1, 2, 3 having sum(duration_sec) > 1000 order by last_event_time desc, duration_sec_bucket, session_id, event_type limit 3
